(window.AUDIO_PAK = window.AUDIO_PAK || {})["pauze-met-collegas"] = {"verteller|-10%|de lunch": "data:audio/mpeg;base64,", "verteller|-10%|de boterham": "data:audio/mpeg;base64,", "verteller|-10%|de koffieautomaat": "data:audio/mpeg;base64,", "verteller|-10%|het weer": "data:audio/mpeg;base64,", "verteller|-10%|praten": "data:audio/mpeg;base64,", "verteller|-10%|het nieuws": "data:audio/mpeg;base64,", "verteller|-10%|het voetbal": "data:audio/mpeg;base64,", "verteller|-10%|Mag ik hier zitten?": "data:audio/mpeg;base64,", "verteller|-10%|Wat eet jij?": "data:audio/mpeg;base64,", "verteller|-10%|Wat een mooi weer vandaag!": "data:audio/mpeg;base64,", "verteller|-10%|Wil je ook koffie?": "data:audio/mpeg;base64,", "verteller|-10%|Heb je het voetbal gezien?": "data:audio/mpeg;base64,", "lotte|-10%|Hoi! Kom je erbij zitten?": "data:audio/mpeg;base64,", "lotte|-10%|Natuurlijk. Wat eet jij?": "data:audio/mpeg;base64,", "lotte|-10%|Lekker. Wat een mooi weer vandaag, hè?": "data:audio/mpeg;base64,", "lotte|-10%|Ja, lekker. Dank je!": "data:audio/mpeg;base64,", "verteller|-10%|de verjaardag": "data:audio/mpeg;base64,", "verteller|-10%|trakteren": "data:audio/mpeg;base64,", "verteller|-10%|feliciteren": "data:audio/mpeg;base64,", "verteller|-10%|het cadeau": "data:audio/mpeg;base64,", "verteller|-10%|het uitje": "data:audio/mpeg;base64,", "verteller|-10%|de taart": "data:audio/mpeg;base64,", "verteller|-10%|Gefeliciteerd met je verjaardag!": "data:audio/mpeg;base64,", "verteller|-10%|Hoe oud ben je geworden?": "data:audio/mpeg;base64,", "verteller|-10%|Ik trakteer op taart.": "data:audio/mpeg;base64,", "verteller|-10%|Dit cadeau is van het team.": "data:audio/mpeg;base64,", "verteller|-10%|Ga je mee met het uitje?": "data:audio/mpeg;base64,", "karim|-10%|Hoi! Ik ben vandaag jarig. Ik trakteer op taart!": "data:audio/mpeg;base64,", "karim|-10%|Dank je! Wil je een stuk taart?": "data:audio/mpeg;base64,", "karim|-10%|Vijfendertig. Ik word oud!": "data:audio/mpeg;base64,", "karim|-10%|Wat lief! Dank jullie wel.": "data:audio/mpeg;base64,", "karim|-10%|Uit eten met mijn familie. En zaterdag is het teamuitje. Ga je mee?": "data:audio/mpeg;base64,", "karim|-10%|We gaan samen bowlen.": "data:audio/mpeg;base64,", "verteller|-10%|het personeelsfeest": "data:audio/mpeg;base64,", "verteller|-10%|de borrel": "data:audio/mpeg;base64,", "verteller|-10%|het afscheid": "data:audio/mpeg;base64,", "verteller|-10%|Vrijdag is er een borrel.": "data:audio/mpeg;base64,", "verteller|-10%|Ik drink liever fris.": "data:audio/mpeg;base64,", "lotte|-10%|Hoi! Hoe was je weekend?": "data:audio/mpeg;base64,", "lotte|-10%|Wat heb je gedaan?": "data:audio/mpeg;base64,", "lotte|-10%|Kom je vrijdag naar de borrel?": "data:audio/mpeg;base64,", "lotte|-10%|Er is ook fris en thee, hoor.": "data:audio/mpeg;base64,", "lotte|-10%|Geef je ook vijf euro voor het cadeau?": "data:audio/mpeg;base64,", "lotte|-10%|Top! Tot vrijdag!": "data:audio/mpeg;base64,", "lotte|+0%|Karim, kom je vrijdag naar de borrel?": "data:audio/mpeg;base64,", "karim|+0%|Welke borrel?": "data:audio/mpeg;base64,", "lotte|+0%|Het afscheid van Wim. Hij gaat met pensioen.": "data:audio/mpeg;base64,", "karim|+0%|O ja! Hoe laat is het?": "data:audio/mpeg;base64,", "lotte|+0%|Om vier uur in de kantine. Er is eten en drinken, ook fris en thee.": "data:audio/mpeg;base64,", "karim|+0%|Fijn, ik drink geen alcohol. Kopen we een cadeau?": "data:audio/mpeg;base64,", "lotte|+0%|Ja, iedereen geeft vijf euro. We kopen een fiets voor hem.": "data:audio/mpeg;base64,", "karim|+0%|Goed idee! Ik geef je straks vijf euro.": "data:audio/mpeg;base64,", "lotte|-10%|Schrijf jij ook iets in de kaart voor Wim?": "data:audio/mpeg;base64,", "verteller|-10%|Beste Wim, bedankt voor je hulp! Veel plezier met je pensioen. Groetjes, Amira": "data:audio/mpeg;base64,"};
